SELECT COUNT(order_id) 
FROM orders 
WHERE status = 'cancelled' AND strftime('%Y-%m', ordered_at) = '2026-08';

SELECT MIN(list_price_cents) AS min_price_cents, MAX(list_price_cents) AS max_price_cents
FROM products
WHERE is_active = 1;

SELECT AVG(quantity) AS avg_quantity_per_line
FROM order_items
WHERE unit_price_cents >= 5000;

SELECT COUNT(DISTINCT product_id) 
FROM order_items 
WHERE quantity >= 3;
